INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('on_this_day_events','54a55b50-e1ad-4e00-813d-daf38d6713be',NULL,1818,1,15,'Society & Human Rights',65,'{"id":"54a55b50-e1ad-4e00-813d-daf38d6713be","ad_day":15,"ad_date":null,"ad_year":1818,"bs_date":null,"country":null,"sources":[],"ad_month":1,"category":"Society & Human Rights","metadata":{"source_dataset":"lennovative/history_alert (Wikipedia-derived)","source_license":"Wikipedia-derived; retain linked-page attribution","translation_status":"translated"},"title_en":"A paper by David Brewster is read to the Royal Society, belatedly announcing his discovery of what we now call the biaxial class of doubly-refracting crystals.  On the same day, Augustin-Jean Fresnel signs a \"supplement\" (submitted four days later) on reflection of polarized light.","title_ne":"डेभिड ब्रुस्टरको एउटा पेपर रोयल सोसाइटीमा पढियो, जसमा ढिलो गरी हामीले अहिले दोब्बर-अपवर्तन गर्ने क्रिस्टलहरूको द्विअक्षीय वर्गको खोजको घोषणा गरिएको थियो। सोही दिन, अगस्टिन-जीन फ्रेस्नेलले ध्रुवीकृत प्रकाशको परावर्तनमा \"पूरक\" (चार दिन पछि पेश गरिएको) मा हस्ताक्षर गर्छन्।","highlight":false,"image_url":null,"published":true,"created_at":"2026-09-19T03:30:14.615698+00:00","event_type":"event","importance":65,"source_url":"https://en.wikipedia.org/wiki/David_Brewster","summary_en":null,"summary_ne":null,"updated_at":"2026-09-19T03:30:14.615698+00:00","source_name":"User-provided historical dataset","country_code":null,"image_credit":null,"image_api_url":"https://en.wikipedia.org/w/api.php?action=query&prop=pageimages&format=json&piprop=thumbnail%7Coriginal&pithumbsize=1200&titles=David%20Brewster&origin=*","image_license":null,"image_caption_en":null,"image_caption_ne":null,"image_page_title":"David Brewster","source_record_id":"0115-1818-e-177ub39","verification_status":"source-backed","event_date_precision":"day"}','2026-09-19T03:30:14.615698+00:00');
